+
+var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);
+
+JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
+Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");
+
+string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
+Console.WriteLine($"Serialized: {json}");
+
+// --- 2. TryGetTypeInfo<T>(): probe without throwing ---
+
+// With the default reflection resolver, any public type should resolve:
+if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
+{
+    Console.WriteLine($"TryGetTypeInfo<Person> succeeded — type: {found!.Type.Name}");
+}
+
+// With a custom resolver that resolves *nothing*, the call returns false
+// instead of throwing:
+var restricted = new JsonSerializerOptions
+{
+    TypeInfoResolver = new NullResolver()
+};
+
+if (restricted.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? notFound))
+{
+    Console.WriteLine("Unexpectedly resolved!");
+}
+else
+{
+    Console.WriteLine("TryGetTypeInfo<Person> returned false — no metadata available");
+}
+
+// --- types ---
+
+public record Person(string Name, int Age);
+
+/// <summary>A resolver that deliberately resolves nothing.</summary>
+file class NullResolver : IJsonTypeInfoResolver
+{
+    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
+}

